import requests
from requests.auth import HTTPBasicAuth

# Replace with your actual provider-specific configuration
PROVIDER_API_HOST = "https://api.provider.com"
PROVIDER_AUTH_TOKEN = "your_auth_token"

def stream_model_output(model_id, output_stream_url):
    headers = {
        "Authorization": f"Bearer {PROVIDER_AUTH_TOKEN}",
        "Content-Type": "application/json"
    }

    response = requests.get(output_stream_url, headers=headers, stream=True)

    if response.status_code == 200:
        for line in response.iter_lines():
            if line:
                yield line.decode('utf-8')
    else:
        raise Exception(f"Failed to stream model output: {response.status_code} - {response.text}")

# Example usage
model_id = "your_model_id"
output_stream_url = f"{PROVIDER_API_HOST}/models/{model_id}/output_stream"

for line in stream_model_output(model_id, output_stream_url):
    print(line)
